<template>
  <div class="page-title"><div><p class="eyebrow">LEARNING OPERATIONS</p><h1>People, processes and assignments</h1></div></div>
  <div class="cards">
    <form v-if="identity.admin" class="card" @submit.prevent="perform('client',{title:client})"><h2>Add a client</h2><label>Client name<input required v-model="client"></label><button :disabled="busy">Create client</button></form>
    <form v-if="identity.admin" class="card" @submit.prevent="perform('process',process)"><h2>Add a process</h2><label>Name<input required v-model="process.title"></label><label>Client<select required v-model="process.client"><option v-for="c in workspace.clients" :key="c.name" :value="c.name">{{ c.title }}</option></select></label><button :disabled="busy">Create process</button></form>
    <form v-if="identity.admin" class="card" @submit.prevent="perform('user',user)"><h2>Create an account</h2><label>Name<input required v-model="user.name"></label><label>Email<input required type="email" v-model="user.email"></label><label>Temporary password<input required type="password" minlength="12" autocomplete="new-password" v-model="user.password"></label><label>Role<select v-model="user.role"><option value="learner">Learner</option><option value="trainer">Trainer</option><option value="admin">Administrator</option></select></label><button :disabled="busy">Create account</button></form>
    <form v-if="identity.admin" class="card" @submit.prevent="perform('access',access)"><h2>Grant trainer process access</h2><label>Trainer<select required v-model="access.member"><option v-for="u in workspace.users" :key="u.name" :value="u.name">{{ u.full_name }}</option></select></label><label>Process<select required v-model="access.process"><option v-for="p in workspace.processes" :key="p.name" :value="p.name">{{ p.title }}</option></select></label><button :disabled="busy">Grant access</button></form>
    <form class="card" @submit.prevent="perform('batch',batch)"><h2>Create a batch</h2><label>Title<input required v-model="batch.title"></label><label>Process<select required v-model="batch.process"><option v-for="p in workspace.processes" :key="p.name" :value="p.name">{{ p.title }}</option></select></label><label>Start date<input required type="date" v-model="batch.start_date"></label><label>End date<input required type="date" v-model="batch.end_date"></label><button :disabled="busy">Create batch</button></form>
    <form class="card" @submit.prevent="perform('batch_member',membership)"><h2>Add a batch member</h2><label>Batch<select required v-model="membership.batch"><option v-for="b in workspace.batches" :key="b.name" :value="b.name">{{ b.title }}</option></select></label><label>Learner<select required v-model="membership.member"><option v-for="u in workspace.users" :key="u.name" :value="u.name">{{ u.full_name }}</option></select></label><button :disabled="busy">Add learner</button><small>Existing assignments do not automatically include new members.</small></form>
    <form class="card" @submit.prevent="perform('course',course)"><h2>Create a course</h2><label>Title<input required v-model="course.title"></label><label>Process<select v-model="course.process"><option value="">Company-wide</option><option v-for="p in workspace.processes" :key="p.name" :value="p.name">{{ p.title }}</option></select></label><label>Description<textarea v-model="course.description"></textarea></label><label v-if="identity.admin"><input type="checkbox" v-model="course.company_wide">Company-wide foundation</label><button :disabled="busy">Create course</button><small>Edit chapters and lessons in the course catalog.</small></form>
    <form class="card" @submit.prevent="assign"><h2>Assign training</h2><label>Training type<select v-model="assignment.type"><option value="course">Course</option><option value="scenario">Standalone AI scenario</option></select></label>
      <label v-if="assignment.type==='course'">Published course<select required v-model="assignment.course"><option v-for="c in workspace.courses.filter(c=>c.published)" :key="c.name" :value="c.name">{{ c.title }}</option></select></label>
      <label v-else>Published scenario<select required v-model="assignment.scenario_version"><option v-for="s in workspace.scenarios.filter(s=>s.published_version)" :key="s.name" :value="s.published_version">{{ s.title }}</option></select></label>
      <label>Recipient<select v-model="assignment.recipient"><option value="batch">Batch</option><option value="member">Individual</option></select></label>
      <label v-if="assignment.recipient==='batch'">Batch<select required v-model="assignment.batch"><option v-for="b in workspace.batches" :key="b.name" :value="b.name">{{ b.title }}</option></select></label>
      <template v-else><label>Learner<select required v-model="assignment.member"><option v-for="u in workspace.users" :key="u.name" :value="u.name">{{ u.full_name }}</option></select></label><label>Process<select required v-model="assignment.process"><option v-for="p in workspace.processes" :key="p.name" :value="p.name">{{ p.title }}</option></select></label></template>
      <label v-if="assignment.type==='scenario'">Required channels<select multiple v-model="assignment.channels"><option>workflow</option><option>chat</option><option>voice</option></select></label><label>Due date and time (Asia/Kolkata)<input type="datetime-local" v-model="assignment.due_date"></label><label><input type="checkbox" v-model="assignment.mandatory">Mandatory</label><button :disabled="busy">Assign training</button>
    </form>
    <form v-if="identity.admin" class="card" @submit.prevent="perform('provider',provider)"><h2>AI provider settings</h2><label>Groq API key<input type="password" v-model="provider.api_key" autocomplete="off"></label><label>Text model<input v-model="provider.text_model"></label><label>Transcription model<input v-model="provider.stt_model"></label><label>Speech model<input v-model="provider.tts_model"></label><label>Voice<input v-model="provider.tts_voice"></label><button :disabled="busy">Save provider settings</button></form>
  </div><p role="status">{{ message }}</p>
</template>
<script setup>
import { reactive, ref } from 'vue'
import { api, requestId } from '../lib/api'
defineProps(['workspace','identity']); const emit=defineEmits(['changed','error'])
const busy=ref(false), message=ref(''), client=ref('')
const process=reactive({title:'',client:''}),user=reactive({name:'',email:'',password:'',role:'learner'}),access=reactive({member:'',process:''}),batch=reactive({title:'',process:'',start_date:'',end_date:''}),membership=reactive({member:'',batch:''}),course=reactive({title:'',process:'',description:'',company_wide:false})
const provider=reactive({api_key:'',text_model:'openai/gpt-oss-120b',stt_model:'whisper-large-v3-turbo',tts_model:'canopylabs/orpheus-v1-english',tts_voice:'troy'})
const assignment=reactive({type:'course',recipient:'batch',course:'',scenario_version:'',batch:'',member:'',process:'',channels:['workflow'],mandatory:true,due_date:''})
async function perform(kind,data){busy.value=true;try{const result=await api('manage',{kind,data:{...data}});message.value='Saved '+(result.name||'settings');user.password='';provider.api_key='';emit('changed')}catch(e){emit('error',e)}finally{busy.value=false}}
async function assign(){busy.value=true;try{const a=assignment;const result=await api('assign',{request_id:requestId(),course:a.type==='course'?a.course:undefined,scenario_version:a.type==='scenario'?a.scenario_version:undefined,batch:a.recipient==='batch'?a.batch:undefined,member:a.recipient==='member'?a.member:undefined,process:a.process,channels:a.channels,mandatory:Number(a.mandatory),due_date:a.due_date.replace('T',' ')||null});message.value='Assigned to '+result.count+' learners';emit('changed')}catch(e){emit('error',e)}finally{busy.value=false}}
</script>
